// # 三个主入口；缸内数据、名单和快捷记录集中在缸详情。
import { TYPES, countLabel, shortCountLabel, membersFor, isBlackShrimp } from './data.js';
import { escapeHTML as e, dayLabel, localDate, timeLabel, relativeTime, latestRecord, recordSummary, filterRecords, feedingMonth } from './logic.js';
import { icon, aquariumArt, animalIcon } from './art.js';
import { options } from './forms.js';
import { APP_VERSION } from './version.js';
export const NAV = [['home', '首页', 'home'], ['history', '记录', 'book'], ['residents', '居民', 'fish']];
const heading = (title, action = '', sub = '') => `<div class="page-heading"><div><h1>${e(title)}</h1>${sub ? `<p>${e(sub)}</p>` : ''}</div>${action}</div>`;
const addButton = (action, label, extra = '') => `<button class="button secondary small" data-action="${action}" ${extra}>${icon('plus', 15)}${label}</button>`;
export function emptyState(title, action = '') {
  return `<div class="empty-state">${animalIcon('fish', 48)}<p>${e(title)}</p>${action}</div>`;
}
export function shell(data, view, issue) {
  const pages = { home: homePage, history: historyPage, residents: residentsPage, tank: tankPage };
  const active = view.page === 'tank' ? 'home' : view.page;
  const nav = size => NAV.map(([id, label, glyph]) => `<a href="#${id}" class="${active === id ? 'active' : ''}" ${active === id ? 'aria-current="page"' : ''}>${icon(glyph, size)}<span>${label}</span></a>`).join('');
  return `<header class="site-header"><div class="header-inner"><a class="brand" href="#home">${animalIcon('fish', 34)}<strong>小小水族日记</strong></a><nav class="desktop-nav" aria-label="主要导航">${nav(18)}</nav><button class="icon-button manager-button" data-action="manager" aria-label="管理与备份">${icon('gear', 21)}</button></div></header><main id="main" tabindex="-1" class="main-wrap">${issue ? `<div class="storage-banner" role="alert"><span>${e(issue)}</span><button class="button small secondary" data-action="raw-export">导出原始数据</button></div>` : ''}${(pages[view.page] || homePage)(data, view)}</main><nav class="bottom-nav" aria-label="手机导航">${nav(23)}</nav>`;
}
function animalChip(a) {
  return `<button class="animal-chip" data-action="edit-animal" data-id="${e(a.id)}" aria-label="修改${e(a.species)}及数量" title="${e(countLabel(a))}">${animalIcon(a.icon || 'fish', 22)}<span>${e(a.species)}${a.uncertain ? '<i class="uncertain-dot" title="物种待确认"></i>' : ''}</span><b>${e(shortCountLabel(a))}</b></button>`;
}
export function quickActions(cid) {
  return `<div class="quick-actions">${['feed', 'siphon', 'topup', 'water', 'observe'].map(type => `<button data-action="record" data-type="${type}" data-container="${e(cid)}" class="quick-${type}" aria-label="${TYPES[type].label}">${icon(TYPES[type].icon, 21)}<span>${TYPES[type].label}</span></button>`).join('')}</div>`;
}
function lastCare(data, cid) {
  return `<div class="last-care">${[['feed', '喂食'], ['water', '换水']].map(([type, label]) => `<span>${label}<b>${e(relativeTime(latestRecord(data, cid, type)?.timestamp))}</b></span>`).join('')}</div>`;
}
function containerCard(data, c) {
  const animals = data.animals.filter(a => a.containerId === c.id);
  return `<article class="tank-card" data-tank="${e(c.id)}"><a class="tank-scene" href="#tank/${encodeURIComponent(c.id)}" aria-label="查看${e(c.name)}的月历和记录">${aquariumArt(c.art || (c.type === 'bucket' ? 'shrimp' : 'goby'), c.id)}<span class="scene-tag">${icon(c.type === 'bucket' ? 'bucket' : 'tank', 13)}${c.type === 'bucket' ? '虾桶' : '鱼缸'}</span></a><div class="tank-body"><div class="tank-title"><a href="#tank/${encodeURIComponent(c.id)}"><h2>${e(c.name)}</h2>${icon('chevron', 13)}</a><button class="icon-button" data-action="edit-container" data-id="${e(c.id)}" aria-label="编辑${e(c.name)}">${icon('pen', 16)}</button></div>${c.dimensions || c.estimatedVolume ? `<p class="dimensions">${e([c.dimensions, c.estimatedVolume].filter(Boolean).join(' · '))}</p>` : ''}<div class="animal-chips">${animals.map(animalChip).join('')}${!animals.length ? addButton('add-animal', '添加居民', `data-container="${e(c.id)}"`) : ''}</div>${lastCare(data, c.id)}${quickActions(c.id)}</div></article>`;
}
export function homePage(data) {
  const today = filterRecords(data, { from: localDate(), to: localDate() });
  return `${heading('我的水族屋', addButton('add-container', '添加缸'), dayLabel(new Date()))}<div class="tank-grid">${data.containers.map(c => containerCard(data, c)).join('')}</div>${data.containers.length ? '' : emptyState('添加第一个缸', addButton('add-container', '添加缸'))}<section class="today-section"><div class="section-toolbar"><h2>今天 <span class="count-tag">${today.length}</span></h2><a class="text-link" href="#history">全部记录 ${icon('chevron', 12)}</a></div><div class="panel">${today.length ? recordList(data, today.slice(0, 6), true) : '<p class="small-empty">今天暂无记录</p>'}</div></section>`;
}
export function recordList(data, records, compact = false, hideContainer = false) {
  const names = Object.fromEntries(data.containers.map(c => [c.id, c.name]));
  return `<div class="record-list">${records.map(r => { const summary = recordSummary(r); return `<article class="record-row" data-record="${e(r.id)}"><time datetime="${e(r.timestamp)}">${timeLabel(r.timestamp)}</time><span class="record-icon ${TYPES[r.type].color}">${icon(TYPES[r.type].icon, 18)}</span><div class="record-content"><div class="record-head"><strong>${TYPES[r.type].label}</strong>${hideContainer ? '' : `<span>${e(names[r.containerId])}</span>`}</div>${summary ? `<p>${e(summary)}</p>` : ''}${r.notes && r.notes !== summary ? `<p class="record-notes">${e(r.notes)}</p>` : ''}${r.photoIds?.length ? `<button class="photo-count" data-action="view-photos" data-id="${e(r.id)}">${icon('camera', 15)}${r.photoIds.length} 张照片</button>` : ''}</div><div class="record-controls"><button class="icon-button" data-action="edit-record" data-id="${e(r.id)}" aria-label="编辑${TYPES[r.type].label}记录">${icon('pen', 16)}</button></div></article>`; }).join('')}</div>`;
}
function groupedRecords(data, records, hideContainer = false) {
  const groups = new Map();
  records.forEach(r => { const day = localDate(r.timestamp); if (!groups.has(day)) groups.set(day, []); groups.get(day).push(r); });
  return [...groups].map(([day, items]) => `<section class="history-group"><h2 class="history-day">${day === localDate() ? '今天' : e(day.slice(5).replace('-', ' / '))}<span>${items.length} 条</span></h2><div class="panel">${recordList(data, items, false, hideContainer)}</div></section>`).join('');
}
export function historyPage(data, view) {
  const records = filterRecords(data, view.filters);
  const rangeInvalid = view.filters.from && view.filters.to && view.filters.from > view.filters.to;
  const active = Object.values(view.filters).some(Boolean);
  return `${heading('记录', addButton('choose-record', '记一笔'))}<div class="history-search-row"><label class="search-box">${icon('search', 19)}<input id="history-search" type="search" data-filter-field="search" value="${e(view.filters.search)}" placeholder="搜索关键词" aria-label="搜索记录关键词"></label><button class="button secondary" data-action="toggle-filters" aria-label="展开筛选" aria-expanded="${view.filtersOpen}">${icon('filter', 18)}筛选</button></div>${view.filtersOpen ? `<div class="panel history-filters">${[['container', '缸', [['', '全部'], ...data.containers.map(c => [c.id, c.name])]], ['type', '类型', [['', '全部'], ...Object.entries(TYPES).map(([id, v]) => [id, v.label])]]].map(([key, label, items]) => `<label class="field"><span>${label}</span><select data-filter-field="${key}">${options(items, view.filters[key])}</select></label>`).join('')}<label class="field"><span>开始日期</span><input type="date" data-filter-field="from" value="${e(view.filters.from)}"></label><label class="field"><span>结束日期</span><input type="date" data-filter-field="to" value="${e(view.filters.to)}"></label></div>` : ''}<div class="results-info"><span>${records.length} 条${active ? ' · 已筛选' : ''}</span>${active ? '<button class="text-link" data-action="clear-filters">清除筛选</button>' : ''}</div><div id="history-results">${rangeInvalid ? '<p class="inline-error" role="alert">开始日期不能晚于结束日期</p>' : records.length ? groupedRecords(data, records.slice(0, view.historyLimit)) + (records.length > view.historyLimit ? '<button class="button secondary load-more" data-action="more-history">加载更多</button>' : '') : emptyState(active ? '未找到相关记录' : '暂无记录')}</div>`;
}
function memberCard(a, m, i, total) {
  return `<button class="member-card" data-action="edit-member" data-animal="${e(a.id)}" data-member="${e(m.id)}" aria-label="编辑${e(m.name || `${a.species} ${i + 1}`)}名字和头像"><span class="member-avatar">${m.avatarId ? `<img data-photo-id="${e(m.avatarId)}" alt="${e(m.name || a.species)}的头像" loading="lazy">` : animalIcon(a.icon || 'fish', 42)}</span><span class="member-name ${m.name ? '' : 'unnamed'}">${e(m.name || (total > 1 ? `${a.species} ${i + 1}` : '取个名字'))}</span>${m.length ? `<small>${e(m.length)}</small>` : ''}<span class="member-edit">${icon('pen', 12)}</span></button>`;
}
export function residentGroup(a) {
  const members = membersFor(a);
  return `<div class="resident-group ${isBlackShrimp(a) ? 'shrimp-group' : ''}"><div class="species-heading"><span>${animalIcon(a.icon || 'fish', 23)}<strong>${e(a.species)}</strong>${a.uncertain ? '<small class="uncertain-badge">待确认</small>' : ''}</span><button class="species-count" data-action="edit-animal" data-id="${e(a.id)}" aria-label="编辑${e(a.species)}及数量">${e(shortCountLabel(a))}${icon('pen', 13)}</button></div>${members.length ? `<div class="members-grid">${members.map((m, i) => memberCard(a, m, i, members.length)).join('')}</div>` : ''}</div>`;
}
export function residentsPage(data, view) {
  const containers = data.containers.filter(c => !view.residentContainer || c.id === view.residentContainer);
  return `${heading('居民', addButton('add-animal', '添加物种'))}<div class="container-tabs" aria-label="按缸查看居民">${[['', '全部'], ...data.containers.map(c => [c.id, c.name])].map(([id, name]) => `<button class="chip ${view.residentContainer === id ? 'selected' : ''}" data-action="resident-filter" data-id="${e(id)}" aria-pressed="${view.residentContainer === id}">${e(name)}</button>`).join('')}</div><div class="residents-grid">${containers.map(c => `<section class="panel resident-panel"><div class="resident-panel-head"><a href="#tank/${encodeURIComponent(c.id)}"><h2>${e(c.name)}</h2>${icon('chevron', 13)}</a><button class="icon-button" data-action="add-animal" data-container="${e(c.id)}" aria-label="为${e(c.name)}添加物种">${icon('plus', 17)}</button></div>${data.animals.filter(a => a.containerId === c.id).map(residentGroup).join('') || '<p class="small-empty">暂无居民</p>'}</section>`).join('')}</div>`;
}
export function tankPage(data, view) {
  const c = data.containers.find(c => c.id === view.tankId);
  if (!c) return emptyState('这个缸已被移除', '<a class="button secondary" href="#home">返回首页</a>');
  const month = feedingMonth(data, c.id, view.month);
  const records = view.selectedDay ? month.records.filter(r => localDate(r.timestamp) === view.selectedDay) : month.records;
  const animals = data.animals.filter(a => a.containerId === c.id);
  return `<a class="back-link" href="#home">${icon('back', 16)}首页</a>${heading(c.name, `<button class="icon-button" data-action="edit-container" data-id="${e(c.id)}" aria-label="编辑${e(c.name)}">${icon('pen', 18)}</button>`, [c.dimensions, c.estimatedVolume].filter(Boolean).join(' · '))}<div class="tank-detail-grid"><section class="tank-detail-main"><div class="panel detail-scene">${aquariumArt(c.art || 'goby', `detail-${c.id}`)}${quickActions(c.id)}</div><section class="panel calendar-panel"><div class="calendar-heading"><h2>喂食月历</h2><div class="month-control"><button class="icon-button" data-action="month" data-offset="-1" aria-label="上个月">${icon('back', 16)}</button><strong>${month.year} / ${String(month.month).padStart(2, '0')}</strong><button class="icon-button" data-action="month" data-offset="1" aria-label="下个月">${icon('chevron', 16)}</button></div></div><div class="month-stats"><div><strong>${month.feedCount}</strong><span>喂食次数</span></div><div><strong>${month.feedDays}</strong><span>记录天数</span></div><div><strong>${month.waterCount}</strong><span>换水次数</span></div><div><strong>${month.observeCount}</strong><span>观察次数</span></div></div><div class="calendar-grid"><div class="weekdays">${['一', '二', '三', '四', '五', '六', '日'].map(day => `<span>${day}</span>`).join('')}</div>${Array.from({ length: month.leading }, () => '<span class="calendar-blank"></span>').join('')}${month.days.map(d => `<button class="calendar-day ${d.feedCount ? 'fed' : ''} ${d.date === localDate() ? 'today' : ''} ${d.date === view.selectedDay ? 'selected' : ''}" data-action="calendar-day" data-date="${d.date}" aria-label="${d.date}，${d.feedCount} 次喂食记录" aria-pressed="${d.date === view.selectedDay}"><span>${d.day}</span>${d.feedCount ? `<b>${d.feedCount}</b>` : '<i></i>'}</button>`).join('')}</div><p class="calendar-legend"><i></i>有喂食记录 <span>空白日期未记录</span></p></section><section class="tank-records"><div class="section-toolbar"><h2>${view.selectedDay ? e(view.selectedDay.slice(5).replace('-', ' / ')) : '本月记录'} <span class="count-tag">${records.length}</span></h2>${view.selectedDay ? '<button class="text-link" data-action="clear-day">整月</button>' : `<button class="text-link" data-action="tank-history" data-container="${e(c.id)}">全部 ${icon('chevron', 12)}</button>`}</div>${records.length ? groupedRecords(data, records.slice(0, 50), true) : '<div class="panel"><p class="small-empty">暂无记录</p></div>'}${records.length > 50 ? `<button class="button secondary load-more" data-action="tank-history" data-container="${e(c.id)}">查看全部 ${records.length} 条</button>` : ''}</section></section><aside class="panel tank-residents"><div class="resident-panel-head"><h2>缸内居民</h2><button class="icon-button" data-action="add-animal" data-container="${e(c.id)}" aria-label="添加物种">${icon('plus', 17)}</button></div>${animals.map(residentGroup).join('') || '<p class="small-empty">暂无居民</p>'}<button class="button secondary other-record" data-action="choose-record" data-container="${e(c.id)}">${icon('plus', 15)}其他记录</button></aside></div>`;
}
export function managerContent(data) {
  return `<div class="manager-summary">${data.containers.length} 个缸 <span>·</span> ${data.records.length} 条记录</div><div class="manager-actions"><button class="button primary" data-action="export-json">${icon('export', 19)}备份（含照片）</button><button class="button secondary" data-action="import">${icon('upload', 19)}恢复备份</button><button class="button secondary" data-action="export-csv">${icon('book', 19)}导出记录表格</button></div><input id="import-file" type="file" accept=".json,application/json" hidden><p class="manager-note">数据与照片保存在当前浏览器。换网址或手机前先备份。</p><details class="manager-danger"><summary>清理记录</summary><button class="button danger-quiet" data-action="clear-records">${icon('trash', 16)}清空全部记录</button></details><p class="manager-version"><span>v${e(APP_VERSION)}</span><a href="./intro.html#updates" target="_blank" rel="noopener">更新说明</a></p>`;
}
